        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'min': 0.0, 'span': 80.0, 'label': 'GAMMA'})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 3, 'min': -1.0, 'span': 10000.0, 'label': 'GAMMA'})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'min': 15.0, 'span': 4080.0, 'label': 'GAMMA'})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'min': 0, 'span': 0, 'label': 'EMPTY'})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'min': 0.0, 'span': 20735.0, 'label': 'GAMMA'})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'min': -1.0, 'span': 0.0, 'label': 'GAMMA'})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'min': 1295.0, 'span': 0.0, 'label': 'GAMMA'})
